package com.valor.auth;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="technician_profiles") public class TechnicianProfile { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @OneToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false,unique=true) User user; @Column(name="employee_id",length=50,unique=true) String employeeId; @Column(name="assigned_area",length=160) String assignedArea; @Column(length=160) String specialization; @Column(name="availability_status",nullable=false,length=20) String availabilityStatus="AVAILABLE"; @Column(precision=3,scale=2) java.math.BigDecimal rating; @Column(name="last_working_day") LocalDate lastWorkingDay; @Column(name="last_active_at") LocalDateTime lastActiveAt; @Column(name="is_active",nullable=false) boolean active=true; @Column(name="created_at",nullable=false) LocalDateTime createdAt; @Column(name="updated_at",nullable=false) LocalDateTime updatedAt; @PrePersist void p(){createdAt=LocalDateTime.now();updatedAt=createdAt;} @PreUpdate void u(){updatedAt=LocalDateTime.now();} public Long getId(){return id;} public User getUser(){return user;} public boolean isActive(){return active;} public String getEmployeeId(){return employeeId;} public String getAssignedArea(){return assignedArea;} public String getSpecialization(){return specialization;} public String getAvailabilityStatus(){return availabilityStatus;} public LocalDateTime getLastActiveAt(){return lastActiveAt;} public void setAvailabilityStatus(String value){availabilityStatus=value;} public void setLastActiveAt(LocalDateTime value){lastActiveAt=value;} }
